_AUTHORITY_LABELS: Final = frozenset(("\ubc1c\uae09\uae30\uad00", "\ud5c8\uac00\uae30\uad00", "\ucc98\ub9ac\uae30\uad00", "\ud5c8\uac00\uad8c\uc790"))
_ISSUED_DATE_LABELS: Final = frozenset(("\ud5c8\uac00\uc77c", "\ubc1c\uae09\uc77c", "\uad50\ubd80\uc77c"))
