_STOP_LABELS: Final = _PERMIT_NUMBER_LABELS | _AUTHORITY_LABELS | _ISSUED_DATE_LABELS | _VALIDITY_LABELS | _CONDITION_LABELS
_PERMIT_KEYWORDS: Final = (
    (PermitType.AIR_EMISSION, ("\ub300\uae30\ubc30\ucd9c\uc2dc\uc124", "\ub300\uae30\uc624\uc5fc\ubb3c\uc9c8\ubc30\ucd9c\uc2dc\uc124")),
