    (PermitType.WATER_EMISSION, ("\ud3d0\uc218\ubc30\ucd9c\uc2dc\uc124", "\uc218\uc9c8\uc624\uc5fc\ubb3c\uc9c8")),
    (PermitType.NONPOINT_SOURCE, ("\ube44\uc810\uc624\uc5fc\uc6d0",)),
    (PermitType.RIVER_WATER_USE, ("\ud558\ucc9c\uc218\uc0ac\uc6a9",)),
    (PermitType.WASTE_DESIGNATED, ("\uc9c0\uc815\ud3d0\uae30\ubb3c",)),
    (PermitType.WASTE_GENERAL, ("\uc0ac\uc5c5\uc7a5\ud3d0\uae30\ubb3c", "\ud3d0\uae30\ubb3c\ucc98\ub9ac")),
