def _compact(value: str) -> str:
    return _SEPARATORS.sub("", value).casefold()


def _bounded(value: str, maximum: int = _MAX_EVIDENCE_CHARACTERS) -> str:
    return value.strip()[:maximum]


def _date_values(value: str) -> tuple[date, ...]:
    values: list[date] = []
    for match in _DATE_PATTERN.finditer(value[:_MAX_LINE_CHARACTERS]):
        try:
            parsed = date(
                int(match.group("year")), int(match.group("month")), int(match.group("day"))
            )
        except ValueError:
            continue
        if parsed not in values:
            values.append(parsed)
    return tuple(values)


def _candidate(
    value: CandidateValue,
    page: ExtractedPage,
    evidence: str,
    source: CandidateSource,
    confidence: Confidence,
) -> FieldCandidate:
    return FieldCandidate(value, page.page_number, _bounded(evidence), page.method, source, confidence)


def _value_key(value: CandidateValue) -> str:
    return value.isoformat() if isinstance(value, date) else value


def _field(candidates: list[FieldCandidate]) -> CandidateField:
    ordered = sorted(
        candidates,
        key=lambda candidate: (
            candidate.page_number,
            _value_key(candidate.value),
            candidate.evidence,
            candidate.source.value,
        ),
    )
    unique: list[FieldCandidate] = []
    keys: set[tuple[str, int]] = set()
    for candidate in ordered:
        key = (_value_key(candidate.value), candidate.page_number)
        if key not in keys:
            keys.add(key)
            unique.append(candidate)
        if len(unique) == _MAX_CANDIDATES_PER_FIELD:
            break
    if not unique:
        return CandidateField((), None, None)
    values = {_value_key(candidate.value) for candidate in unique}
    top_rank = max(_CONFIDENCE_RANK[candidate.confidence] for candidate in unique)
    top_values = {
        _value_key(candidate.value)
        for candidate in unique
        if _CONFIDENCE_RANK[candidate.confidence] == top_rank
    }
    conflict_reason = "conflicting values across pages" if len(values) > 1 else None
    if len(top_values) > 1:
        return CandidateField(tuple(unique), None, "conflicting top-confidence values")
    selected = next(candidate for candidate in unique if _CONFIDENCE_RANK[candidate.confidence] == top_rank)
    return CandidateField(tuple(unique), selected, conflict_reason)


def _alias_pattern(alias: str) -> re.Pattern[str]:
    characters = tuple(character for character in alias.strip() if not character.isspace())
    joined = r"[\s\-_/\u00b7]*".join(re.escape(character) for character in characters)
    return re.compile(rf"(?<![0-9A-Za-z]){joined}(?![0-9A-Za-z])", re.IGNORECASE)


def _site_candidates(pages: tuple[ExtractedPage, ...], sites: tuple[SiteRef, ...]) -> list[FieldCandidate]:
    candidates: list[FieldCandidate] = []
    for site in sites:
        aliases = (site.code, site.name, *site.aliases)
        for alias in aliases:
            if len(_compact(alias)) < _MIN_ALIAS_COMPACT_LENGTH:
                continue
            pattern = _alias_pattern(alias)
            for page in pages:
                match = pattern.search(page.text[:_MAX_PAGE_CHARACTERS])
                if match is None:
                    continue
                evidence = match.group(0)
                confidence = Confidence.HIGH if evidence.casefold() == alias.casefold() else Confidence.MEDIUM
                candidates.append(
                    _candidate(site.site_id, page, evidence, CandidateSource.KNOWN_SITE_ALIAS, confidence)
                )
    return candidates


@dataclass(slots=True)
class _LabeledFields:
    permit_numbers: list[FieldCandidate]
    authorities: list[FieldCandidate]
    issued_dates: list[FieldCandidate]
    valid_from: list[FieldCandidate]
    valid_until: list[FieldCandidate]


def _append_number(fields: _LabeledFields, page: ExtractedPage, line: str, value: str) -> None:
    number = _PERMIT_NUMBER_VALUE.search(value)
    if number is not None:
        fields.permit_numbers.append(
            _candidate(number.group(0), page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH)
        )


def _append_authority(fields: _LabeledFields, page: ExtractedPage, line: str, value: str) -> None:
    authority = _bounded(value, 120)
    if authority:
        fields.authorities.append(
            _candidate(authority, page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH)
        )


def _append_issued_dates(fields: _LabeledFields, page: ExtractedPage, line: str, value: str) -> None:
    for parsed in _date_values(value):
        fields.issued_dates.append(
            _candidate(parsed, page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH)
        )


def _append_validity(fields: _LabeledFields, page: ExtractedPage, line: str, value: str) -> None:
    parsed_dates = _date_values(value)
    if parsed_dates:
        fields.valid_from.append(
            _candidate(parsed_dates[0], page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH)
        )
    if len(parsed_dates) > 1:
        fields.valid_until.append(
            _candidate(parsed_dates[1], page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH)
        )


def _append_labeled_candidate(fields: _LabeledFields, page: ExtractedPage, line: str) -> None:
    match = _LABELED_LINE.match(line)
    if match is None:
        return
    label = _compact(match.group("label"))
    value = match.group("value").strip()
    if label in _PERMIT_NUMBER_LABELS:
        _append_number(fields, page, line, value)
    elif label in _AUTHORITY_LABELS:
        _append_authority(fields, page, line, value)
    elif label in _ISSUED_DATE_LABELS:
        _append_issued_dates(fields, page, line, value)
    elif label in _VALIDITY_LABELS:
        _append_validity(fields, page, line, value)


def _labeled_candidates(pages: tuple[ExtractedPage, ...]) -> _LabeledFields:
    fields = _LabeledFields([], [], [], [], [])
    for page in pages:
        for line in page.text[:_MAX_PAGE_CHARACTERS].splitlines():
            _append_labeled_candidate(fields, page, line[:_MAX_LINE_CHARACTERS])
    return fields


def _permit_type_candidates(pages: tuple[ExtractedPage, ...]) -> list[FieldCandidate]:
    candidates: list[FieldCandidate] = []
    for page in pages:
        lines = page.text[:_MAX_PAGE_CHARACTERS].splitlines()
        for line in lines:
            bounded_line = line[:_MAX_LINE_CHARACTERS]
            compact_line = _compact(bounded_line)
            for permit_type, keywords in _PERMIT_KEYWORDS:
                if any(_compact(keyword) in compact_line for keyword in keywords):
                    confidence = (
                        Confidence.HIGH
                        if any(token in compact_line for token in ("\ud5c8\uac00", "\uc2e0\uace0", "\ub4f1\ub85d"))
                        else Confidence.MEDIUM
                    )
                    candidates.append(
                        _candidate(
                            permit_type.value,
                            page,
                            bounded_line,
                            CandidateSource.PERMIT_KEYWORD,
                            confidence,
                        )
                    )
    return candidates


def _condition_candidates(pages: tuple[ExtractedPage, ...]) -> list[FieldCandidate]:
    candidates: list[FieldCandidate] = []
    for page in pages:
        lines = page.text[:_MAX_PAGE_CHARACTERS].splitlines()
        for index, line in enumerate(lines):
            bounded_line = line[:_MAX_LINE_CHARACTERS]
            match = _LABELED_LINE.match(bounded_line)
            if match is None or _compact(match.group("label")) not in _CONDITION_LABELS:
                continue
            parts = [match.group("value").strip()]
            for following in lines[index + 1 : index + 9]:
                bounded_following = following[:_MAX_LINE_CHARACTERS]
                if not bounded_following.strip():
                    break
                next_match = _LABELED_LINE.match(bounded_following)
                if next_match is not None and _compact(next_match.group("label")) in _STOP_LABELS:
                    break
                parts.append(bounded_following.strip())
            value = "\n".join(part for part in parts if part)[:_MAX_CONDITIONS_CHARACTERS]
            if value:
                evidence = "\n".join([bounded_line, *parts[1:]])[:_MAX_EVIDENCE_CHARACTERS]
                candidates.append(
                    _candidate(value, page, evidence, CandidateSource.MULTILINE_LABEL, Confidence.HIGH)
                )
    return candidates


def extract_candidates(
    pages: tuple[ExtractedPage, ...], known_sites: tuple[SiteRef, ...]
) -> PermitCandidates:
    """Extract bounded, review-only candidate fields without mutating permit data."""
    labeled = _labeled_candidates(pages)
    return PermitCandidates(
        site=_field(_site_candidates(pages, known_sites)),
        permit_type=_field(_permit_type_candidates(pages)),
        permit_number=_field(labeled.permit_numbers),
        authority=_field(labeled.authorities),
        issued_on=_field(labeled.issued_dates),
        valid_from=_field(labeled.valid_from),
        valid_until=_field(labeled.valid_until),
        conditions=_field(_condition_candidates(pages)),
    )

from __future__ import annotations

from dataclasses import dataclass
from datetime import date
from typing import TYPE_CHECKING, Final

from .field_models import CandidateField, CandidateSource, CandidateValue, Confidence, FieldCandidate, PermitCandidates, SiteRef
from .field_rules import (
    AUTHORITY_LABELS,
    CONDITION_LABELS,
    ISSUED_DATE_LABELS,
    PERMIT_CONTEXT,
    PERMIT_KEYWORDS,
    PERMIT_NUMBER_LABELS,
    PERMIT_NUMBER_VALUE,
    VALIDITY_LABELS,
    alias_pattern,
    compact,
    condition_boundary,
    date_values,
    is_permit_context,
    labeled_line,
)

if TYPE_CHECKING:
    from .models import ExtractedPage

__all__ = (
    "CandidateField",
    "CandidateSource",
    "Confidence",
    "FieldCandidate",
    "PermitCandidates",
    "SiteRef",
    "extract_candidates",
)

_MAX_PAGE_CHARACTERS: Final = 200_000
_MAX_LINE_CHARACTERS: Final = 2_000
_MAX_EVIDENCE_CHARACTERS: Final = 240
_MAX_CONDITIONS_CHARACTERS: Final = 1_200
_MAX_CANDIDATES_PER_FIELD: Final = 24
_MIN_ALIAS_COMPACT_LENGTH: Final = 3
_RANK: Final = {Confidence.HIGH: 3, Confidence.MEDIUM: 2, Confidence.LOW: 1}


@dataclass(slots=True)
class _LabeledFields:
    permit_numbers: list[FieldCandidate]
    authorities: list[FieldCandidate]
    issued_dates: list[FieldCandidate]
    valid_from: list[FieldCandidate]
    valid_until: list[FieldCandidate]


def _bounded(value: str, maximum: int = _MAX_EVIDENCE_CHARACTERS) -> str:
    return value.strip()[:maximum]


def _candidate(
    value: CandidateValue,
    page: ExtractedPage,
    evidence: str,
    source: CandidateSource,
    confidence: Confidence,
) -> FieldCandidate:
    return FieldCandidate(value, page.page_number, _bounded(evidence), page.method, source, confidence)


def _value_key(value: CandidateValue) -> str:
    return value.isoformat() if isinstance(value, date) else value


def _field(candidates: list[FieldCandidate]) -> CandidateField:
    ordered = sorted(
        candidates,
        key=lambda item: (item.page_number, _value_key(item.value), -_RANK[item.confidence], item.evidence, item.method.value, item.source.value),
    )
    retained: list[FieldCandidate] = []
    seen: set[tuple[str, int]] = set()
    for candidate in ordered:
        key = (_value_key(candidate.value), candidate.page_number)
        if key not in seen:
            seen.add(key)
            retained.append(candidate)
        if len(retained) == _MAX_CANDIDATES_PER_FIELD:
            break
    if not retained:
        return CandidateField((), None, None)
    values = {_value_key(candidate.value) for candidate in retained}
    strongest = max(_RANK[candidate.confidence] for candidate in retained)
    strongest_values = {_value_key(candidate.value) for candidate in retained if _RANK[candidate.confidence] == strongest}
    if len(strongest_values) > 1:
        return CandidateField(tuple(retained), None, "conflicting top-confidence values")
    selected = next(candidate for candidate in retained if _RANK[candidate.confidence] == strongest)
    conflict = "conflicting values across pages" if len(values) > 1 else None
    return CandidateField(tuple(retained), selected, conflict)


def _site_candidates(pages: tuple[ExtractedPage, ...], sites: tuple[SiteRef, ...]) -> list[FieldCandidate]:
    candidates: list[FieldCandidate] = []
    for site in sites:
        for alias in (site.code, site.name, *site.aliases):
            if len(compact(alias)) < _MIN_ALIAS_COMPACT_LENGTH:
                continue
            pattern = alias_pattern(alias)
            for page in pages:
                match = pattern.search(page.text[:_MAX_PAGE_CHARACTERS])
                if match is not None:
                    evidence = match.group(0)
                    confidence = Confidence.HIGH if evidence.casefold() == alias.casefold() else Confidence.MEDIUM
                    candidates.append(_candidate(site.site_id, page, evidence, CandidateSource.KNOWN_SITE_ALIAS, confidence))
    return candidates


def _append_labeled(fields: _LabeledFields, page: ExtractedPage, line: str) -> None:
    labeled = labeled_line(line)
    if labeled is None:
        return
    label, value = labeled
    if label in PERMIT_NUMBER_LABELS:
        number = PERMIT_NUMBER_VALUE.search(value)
        if number is not None:
            fields.permit_numbers.append(_candidate(number.group(0), page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH))
    elif label in AUTHORITY_LABELS and value:
        fields.authorities.append(_candidate(_bounded(value, 120), page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH))
    elif label in ISSUED_DATE_LABELS:
        fields.issued_dates.extend(_candidate(item, page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH) for item in date_values(value))
    elif label in VALIDITY_LABELS:
        dates = date_values(value)
        if dates:
            fields.valid_from.append(_candidate(dates[0], page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH))
        if len(dates) > 1:
            fields.valid_until.append(_candidate(dates[1], page, line, CandidateSource.LABELED_VALUE, Confidence.HIGH))


def _labeled_candidates(pages: tuple[ExtractedPage, ...]) -> _LabeledFields:
    fields = _LabeledFields([], [], [], [], [])
    for page in pages:
        for line in page.text[:_MAX_PAGE_CHARACTERS].splitlines():
            _append_labeled(fields, page, line[:_MAX_LINE_CHARACTERS])
    return fields


def _permit_type_candidates(pages: tuple[ExtractedPage, ...]) -> list[FieldCandidate]:
    candidates: list[FieldCandidate] = []
    for page in pages:
        lines = [line[:_MAX_LINE_CHARACTERS] for line in page.text[:_MAX_PAGE_CHARACTERS].splitlines()]
        for index, line in enumerate(lines):
            normalized = compact(line)
            direct_context, nearby_context = is_permit_context(lines, index)
            for permit_type, keywords in PERMIT_KEYWORDS:
                for keyword, requires_context in keywords:
                    if compact(keyword) not in normalized or (requires_context and not nearby_context):
                        continue
                    confidence = Confidence.HIGH if direct_context else Confidence.MEDIUM
                    candidates.append(_candidate(permit_type.value, page, line, CandidateSource.PERMIT_KEYWORD, confidence))
                    break
